    collections::{BTreeMap, BTreeSet},
    sync::Arc,
};

#[derive(Default, Clone)]
struct Slot {
    sequence: u32,
    owner: Option<ConnId>,
    data: Option<Arc<Vec<u8>>>,
    available: bool,
    readback: bool,
    remote_payload: Option<Arc<ClipboardData>>,
}
#[derive(Clone)]
pub struct Server {
    config: Arc<Config>,
    peers: BTreeMap<ConnId, Peer>,
    metadata: BTreeMap<ConnId, Option<String>>,
    layout: Layout,
    primary: usize,
    active: usize,
    cursor: (i32, i32),
    last_motion: (i32, i32),
    now: u64,
    sequence: u32,
    local: Ledger,
    hotkey: Option<Hotkey>,
    hotkey_held: Ledger,
    opts: Options,
    slots: [Slot; 2],
}
impl Server {
    pub fn new(config: Arc<Config>) -> Self {
        let primary = config.screens.iter().position(|s| s.name == config.name).unwrap_or(0);
        let layout = Layout::from_config(&config).unwrap_or_else(|e| {
            log::warn!("invalid layout: {e:?}");
            Layout::empty()
        });
        let cursor = layout.rect(primary).center();
        let mut opts = Options::default();
        opts.apply(&config_options(&config, true));
        let hotkey = config.hotkeys.lock_to_screen.as_deref().and_then(Hotkey::parse);
        Self {
            config,
            peers: BTreeMap::new(),
            metadata: BTreeMap::new(),
            layout,
            primary,
            active: primary,
            cursor,
            last_motion: (0, 0),
            now: 0,
            sequence: 0,
            local: Ledger::default(),
            hotkey,
            hotkey_held: Ledger::default(),
            opts,
            slots: [Slot::default(), Slot::default()],
        }
    }
    pub fn abort_clipboard(&mut self, conn: ConnId, id: ClipboardId) {
        if let Some(peer) = self.peers.get_mut(&conn) {
            peer.transfers.cancel(id);
        }
    }
    pub fn next_deadline_ms(&self) -> u64 {
        self.peers
            .values()
            .map(|p| p.next_deadline(self.now, true))
            .min()
            .unwrap_or(self.now + 1000)
            .min(self.layout.next_deadline(self.now))
    }
    pub fn config(&self) -> &Config {
        &self.config
    }
    pub fn remote_active(&self) -> bool {
        self.active != self.primary
    }
    pub fn is_connected(&self) -> bool {
        self.peers.values().any(|p| p.phase == Phase::Ready)
    }
    pub fn snapshot(&self) -> SessionSnapshot {
        SessionSnapshot {
            active_screen: Some(self.name(self.active).into()),
            cursor: Some(self.cursor),
            peers: self.peers.iter().map(|(&c, p)| p.snapshot(c)).collect(),
            connected: self.peers.values().any(|p| p.phase == Phase::Ready),
            remote_active: self.active != self.primary,
        }
    }
    fn name(&self, s: usize) -> &str {
        self.config
            .screens
            .get(s)
            .map(|s| s.name.as_str())
            .unwrap_or(&self.config.name)
    }
    fn screen(&self, name: &str) -> Option<usize> {
        self.config
            .screens
            .iter()
            .position(|s| s.name == name || s.aliases.iter().any(|a| a == name))
    }
    fn connection(&self, s: usize) -> Option<ConnId> {
        let name = self.name(s);
        self.peers
            .iter()
            .find(|(_, p)| p.phase == Phase::Ready && p.name == name)
            .map(|(&c, _)| c)
    }
    fn leave(&mut self, out: &mut Vec<Action>) {
        if self.active != self.primary {
            if let Some(conn) = self.connection(self.active) {
                if let Some(p) = self.peers.get_mut(&conn) {
                    p.ledger.release_remote(conn, out);
                    p.secure_input = None;
                }
                out.push(Action::SendControl {
                    conn,
                    msg: Message::Leave,
                });
            }
        }
        self.active = self.primary;
        self.local.clear();
        self.hotkey_held.clear();
        self.layout.reset();
        self.cursor = self.layout.rect(self.primary).center();
        out.push(Action::ReleaseAllLocal);
        out.push(Action::HideLocalCursor(false));
        out.push(Action::WarpLocalCursor {
            x: self.cursor.0,
            y: self.cursor.1,
        });
    }
    fn remove(&mut self, conn: ConnId, out: &mut Vec<Action>) {
        if self.connection(self.active) == Some(conn) {
            self.leave(out);
        }
        if let Some(p) = self.peers.remove(&conn) {
            notify("peer.disconnected", serde_json::json!({"name":p.name}), out);
            for slot in &mut self.slots {
                if slot.owner == Some(conn) {
                    slot.owner = None;
                }
            }
        }
        self.metadata.remove(&conn);
    }
    fn fail(&mut self, conn: ConnId, msg: Message, out: &mut Vec<Action>) {
        send(conn, msg, out);
        self.remove(conn, out);
        close(conn, CloseReason::BadFrame, out);
    }
    pub fn handle(&mut self, ev: ServerEvent, out: &mut Vec<Action>) {
        match ev {
            ServerEvent::ClientConnected { conn } => {
                let mut p = Peer::new(self.now);
                p.fingerprint = self.metadata.remove(&conn).flatten();
                p.options.heartbeat = self.config.server.heartbeat_ms;
                self.peers.insert(conn, p);
                send(
                    conn,
                    Message::Hello {
                        product: if self.config.options.barrier {
                            "Barrier"
                        } else {
                            "Synergy"
                        }
                        .into(),
                        version: ProtocolVersion {
                            major: 1,
                            minor: if self.config.options.barrier { 6 } else { 8 },
                        },
                    },
                    out,
                );
            }
            ServerEvent::ConnectionMetadata { conn, fingerprint } => {
                if let Some(p) = self.peers.get_mut(&conn) {
                    p.fingerprint = fingerprint;
                } else {
                    self.metadata.insert(conn, fingerprint);
                }
            }
            ServerEvent::ClientMessage { conn, msg } => self.message(conn, msg, out),
            ServerEvent::ClientDisconnected { conn, .. } => self.remove(conn, out),
            ServerEvent::LocalInput(ev) => self.input(ev, out),
            ServerEvent::LocalScreen { rect, cursor } => {
                if self.layout.rect(self.primary) != rect {
                    self.layout.set_rect(self.primary, rect);
                }
                if self.active == self.primary {
                    self.cursor = rect.clamp(cursor.0, cursor.1);
                }
            }
            ServerEvent::DisplayChanged => {
                self.leave(out);
            }
            ServerEvent::LocalClipboardChanged { id } => {
                if id.0 < 2 && self.config.clipboard.enabled && self.config.clipboard.send {
                    if let Some(slot) = self.slots.get_mut(id.0 as usize) {
                        slot.sequence = self.sequence;
                        slot.owner = None;
                        slot.data = None;
                        slot.available = false;
                        slot.readback = false;
                        slot.remote_payload = None;
                    }
                    for p in self.peers.values_mut() {
                        p.transfers.cancel(id);
                    }
                    out.push(Action::ReadClipboard {
                        id,
                        max_bytes: self.config.clipboard.max_bytes.min(clipboard::HARD_CAP),
                    });
                }
            }
            ServerEvent::ClipboardPayload { id, data } => self.payload(None, id, data, out),
            ServerEvent::ClipboardReadFailed { id } => {
                if let Some(slot) = self.slots.get_mut(id.0 as usize) {
                    slot.readback = false;
                }
            }
            ServerEvent::TimerTick { now_ms } => {
                self.now = now_ms;
                let dead = self
                    .peers
                    .iter_mut()
                    .filter_map(|(&c, p)| p.tick(c, now_ms, true, out).then_some(c))
                    .collect::<Vec<_>>();
                // Transfers own their shared blobs until End is queued. Keep
                // only the shared current payload after the final sender.
                for slot in &mut self.slots {
                    if slot.data.as_ref().is_some_and(|data| Arc::strong_count(data) == 1) {
                        slot.data = None;
                    }
                }
                for c in dead {
                    log::warn!("peer heartbeat/setup timeout");
                    self.remove(c, out);
                    close(c, CloseReason::Normal, out);
                }
                if self.last_motion != (0, 0) && self.layout.waiting() {
                    self.motion(
                        self.cursor.0,
                        self.cursor.1,
                        self.last_motion.0,
                        self.last_motion.1,
                        out,
                    );
                }
            }
            ServerEvent::ConfigChanged(cfg) => {
                self.leave(out);
                let clipboard_changed = self.config.clipboard != cfg.clipboard;
                self.config = cfg;
                self.primary = self
                    .config
                    .screens
                    .iter()
                    .position(|s| s.name == self.config.name)
                    .unwrap_or(0);
                self.active = self.primary;
                self.layout = Layout::from_config(&self.config).unwrap_or_else(|_| Layout::empty());
                self.opts = Options::default();
                self.opts.apply(&config_options(&self.config, true));
                self.hotkey = self.config.hotkeys.lock_to_screen.as_deref().and_then(Hotkey::parse);
                // Resolve aliases against the new layout before routing by its
                // canonical names. A merge must retain only one screen owner.
                let mut owners = BTreeSet::new();
                let mut adopted = Vec::new();
                let mut invalid = Vec::new();
                for (&c, p) in &self.peers {
                    if p.phase == Phase::Ready {
                        if let Some(screen) = self.screen(&p.name).filter(|s| *s != self.primary && owners.insert(*s)) {
                            adopted.push((c, self.name(screen).to_string()));
                        } else {
                            invalid.push(c);
                        }
                    }
                }
                for c in invalid {
                    self.remove(c, out);
                    close(c, CloseReason::Normal, out);
                }
                for (c, name) in adopted {
                    if let Some(p) = self.peers.get_mut(&c) {
                        p.name = name;
                    }
                }
                // Config rectangles describe layout placement. DINF supplies
                // the actual screen-local dimensions and origin for each peer.
                for p in self.peers.values() {
                    if p.phase == Phase::Ready {
                        if let Some(screen) = self.screen(&p.name) {
                            self.layout.set_rect(screen, p.screen);
                        }
                    }
                }
                if clipboard_changed {
                    for slot in &mut self.slots {
                        slot.readback = false;
                    }
                }
                for (&c, p) in &mut self.peers {
                    if clipboard_changed {
                        p.transfers = Default::default();
                    }
                    if p.phase == Phase::Ready {
                        send(c, Message::ResetOptions, out);
                        send(
                            c,
                            Message::SetOptions {
                                options: screen_options(&self.config, &p.name),
                            },
                            out,
                        );
                    }
                }
                if self.config.role != Role::Server {
                    self.shutdown(out);
                }
            }
            ServerEvent::CaptureOverflow => self.leave(out),
            ServerEvent::PermissionLost => {
                self.leave(out);
                notice("permission_denied", "Input permission lost", out);
            }
            ServerEvent::LocalSecureInput { app } => {
                if let Some(name) = app {
                    let name = name
                        .chars()
                        .scan(0usize, |len, c| {
                            *len += c.len_utf8();
                            (*len <= 255).then_some(c)
                        })
                        .collect::<String>();
                    for (&conn, p) in &self.peers {
                        if p.phase == Phase::Ready && p.version.minor >= 7 {
                            send(conn, Message::SecureInputNotification { name: name.clone() }, out);
                        }
                    }
                }
            }
            ServerEvent::LocalScreenSaver { on } => {
                for (&conn, p) in &self.peers {
                    if p.phase == Phase::Ready {
                        send(conn, Message::ScreenSaver { on }, out);
                    }
                }
            }
            ServerEvent::Shutdown => self.shutdown(out),
        }
    }
    fn shutdown(&mut self, out: &mut Vec<Action>) {
        self.leave(out);
        for &c in self.peers.keys() {
            send(c, Message::Bye, out);
        }
        self.peers.clear();
    }
    fn message(&mut self, conn: ConnId, msg: Message, out: &mut Vec<Action>) {
        let Some(p) = self.peers.get_mut(&conn) else { return };
        p.last_rx = self.now;
        p.observe_language(&msg);
        if let Message::Unknown { code, .. } = msg {
            p.unknown(code);
            return;
        }
        if matches!(msg, Message::Bye) {
            log::info!("peer goodbye");
            self.remove(conn, out);
            close(conn, CloseReason::Normal, out);
            return;
        }
        if p.phase == Phase::Hello {
            if let Message::HelloBack { product, version, name } = msg {
                if version.major != 1 || version.minor > 8 {
                    self.fail(conn, Message::ErrorIncompatible { major: 1, minor: 8 }, out);
                    return;
                }
                p.product = product;
                p.version = version;
                p.name = name;
                p.phase = Phase::Info;
                send(conn, Message::QueryInfo, out);
                if version.minor >= 8 {
                    send(
                        conn,
                        Message::LanguageSync {
                            languages: String::new(),
                        },
                        out,
                    );
                }
            } else {
                self.fail(conn, Message::ErrorBad, out);
            }
            return;
        }
        if let Message::ScreenInfo { x, y, w, h, .. } = msg {
            if w <= 0 || h <= 0 {
                self.fail(conn, Message::ErrorBad, out);
                return;
            }
            p.screen = Rect {
                x: i32::from(x),
                y: i32::from(y),
                w: i32::from(w),
                h: i32::from(h),
            };
            send(conn, Message::InfoAck, out);
            if p.phase == Phase::Info {
                let name = p.name.clone();
                let fingerprint = p.fingerprint.clone();
                let Some(screen) = self.screen(&name) else {
                    self.fail(conn, Message::ErrorUnknown, out);
                    return;
                };
                if screen == self.primary {
                    self.fail(conn, Message::ErrorUnknown, out);
                    return;
                }
                let canonical = self.name(screen).to_string();
                let existing = self
                    .peers
                    .iter()
                    .find(|(c, p)| **c != conn && p.phase == Phase::Ready && p.name == canonical)
                    .map(|(&c, p)| (c, p.last_rx, p.options.heartbeat, p.fingerprint.clone()));
                if let Some((old, last, hb, fp)) = existing {
                    if (hb > 0 && self.now.saturating_sub(last) >= hb)
                        || fingerprint.as_ref().is_some_and(|n| Some(n) == fp.as_ref())
                    {
                        self.remove(old, out);
                        close(old, CloseReason::Replaced, out);
                        out.push(Action::ReplaceConnection { old, new: conn });
                    } else {
                        log::warn!("healthy duplicate name rejected (EBSY)");
                        self.fail(conn, Message::ErrorBusy, out);
                        return;
                    }
                }
                if let Some(p) = self.peers.get_mut(&conn) {
                    p.name = canonical.clone();
                    p.phase = Phase::Ready;
                    self.layout.set_rect(screen, p.screen);
                }
                send(conn, Message::ResetOptions, out);
                send(
                    conn,
                    Message::SetOptions {
                        options: screen_options(&self.config, &canonical),
                    },
                    out,
                );
                notify("peer.connected", serde_json::json!({"name":canonical}), out);
                self.push_slots(conn, out);
            } else if let Some(screen) = self.peers.get(&conn).and_then(|p| self.screen(&p.name)) {
                if let Some(p) = self.peers.get(&conn) {
                    self.layout.set_rect(screen, p.screen);
                }
            }
            return;
        }
        let Some(p) = self.peers.get_mut(&conn) else { return };
        // A hello alone does not adopt a screen or grant clipboard ownership.
        if p.phase != Phase::Ready {
            return;
        }
        match msg {
            Message::KeepAlive => {
                p.alive(self.now);
            }
            // CROP and DSOP only travel from server to client. Accepting them
            // here lets a peer disable the host's heartbeat and timeout.
            Message::SetOptions { .. } | Message::ResetOptions => {}
            Message::ClipboardGrab { id, sequence }
                if id.0 == 0 && self.config.clipboard.enabled && self.config.clipboard.receive =>
            {
                if let Some(slot) = self.slots.get_mut(id.0 as usize) {
                    if sequence >= slot.sequence {
                        slot.sequence = sequence;
                        slot.owner = Some(conn);
                        slot.data = None;
                        slot.available = false;
                        slot.readback = false;
                        slot.remote_payload = None;
                        for peer in self.peers.values_mut() {
                            peer.transfers.cancel(id);
                        }
                    }
                }
            }
            Message::ClipboardData { id, sequence, chunk }
                if id.0 == 0 && self.config.clipboard.enabled && self.config.clipboard.receive =>
            {
                let valid = self
                    .slots
                    .get(id.0 as usize)
                    .is_some_and(|s| s.owner == Some(conn) && sequence >= s.sequence);
                if valid {
                    let declared = if let openergy_protocol::Chunk::Start { total_len } = &chunk {
                        Some(*total_len as usize)
                    } else {
                        None
                    };
                    match p
                        .transfers
                        .receive(id, sequence, chunk, self.config.clipboard.max_bytes, self.now)
                    {
                        Ok(Some(data)) => self.payload(Some(conn), id, data, out),
                        Ok(None) => {}
                        Err(clipboard::ClipboardError::TooLarge) => clipboard::blocked(
                            declared.unwrap_or(0),
                            self.config.clipboard.max_bytes.min(clipboard::HARD_CAP),
                            &p.name,
                            out,
                        ),
                        Err(e) => {
                            log::warn!("discarded clipboard: {e:?}");
                        }
                    }
                }
            }
            Message::SecureInputNotification { name } => p.secure_input = (!name.is_empty()).then_some(name),
            Message::FileTransfer { payload, .. } => p.decline(payload.len(), out),
            Message::DragInfo { payload, .. } => p.decline(payload.len(), out),
            Message::Noop | Message::ScreenSaver { .. } | Message::LanguageSync { .. } => {}
            _ => {}
        }
    }
    fn input(&mut self, ev: InputEvent, out: &mut Vec<Action>) {
        // Capture state still observes consumed triggers, so mouse-button and
        // modifier switch gates reflect the physical input until its release.
        self.local.observe(&ev);
        let held = match ev {
            InputEvent::KeyDown { key, button, .. }
            | InputEvent::KeyUp { key, button, .. }
            | InputEvent::KeyRepeat { key, button, .. } => self.hotkey_held.has_key(key, button),
            InputEvent::MouseDown { button } | InputEvent::MouseUp { button } => {
                self.hotkey_held.buttons.contains(&button)
            }
            _ => false,
        };
        if held {
            self.hotkey_held.observe(&ev);
            return;
        }
        let hotkey = !self.opts.disable_lock && self.hotkey.is_some_and(|key| key.matches(&ev, self.local.modifiers));
        if (matches!(ev, InputEvent::KeyDown { key: 0xef14, .. }) || hotkey) && !self.opts.disable_lock {
            self.opts.locked = !self.opts.locked;
            self.layout.reset();
        }
        if hotkey {
            self.hotkey_held.observe(&ev);
            return;
        }
        match ev {
            InputEvent::MouseMoveAbs { x, y } => {
                let dx = x.saturating_sub(self.cursor.0);
                let dy = y.saturating_sub(self.cursor.1);
                self.motion(x, y, dx, dy, out);
            }
            InputEvent::MouseMoveRel { dx, dy } => {
                if self.active != self.primary && self.opts.locked && !self.opts.disable_lock && self.opts.relative {
                    if let Some(c) = self.connection(self.active) {
                        send(
                            c,
                            Message::MouseMoveRel {
                                dx: i16c(dx),
                                dy: i16c(dy),
                            },
                            out,
                        );
                    }
                } else {
                    self.motion(
                        self.cursor.0.saturating_add(dx),
                        self.cursor.1.saturating_add(dy),
                        dx,
                        dy,
                        out,
                    );
                }
            }
            _ => {
                if let Some(c) = self.connection(self.active) {
                    if let Some(p) = self.peers.get_mut(&c) {
                        p.ledger.observe(&ev);
                        send(c, wire_input(&ev, p.version.minor, &self.config), out);
                    }
                }
            }
        }
    }
    fn motion(&mut self, x: i32, y: i32, dx: i32, dy: i32, out: &mut Vec<Action>) {
        self.last_motion = (dx, dy);
        let can_switch = self.local.buttons.is_empty()
            && (!self.opts.locked || self.opts.disable_lock)
            && (self.local.modifiers & self.opts.needs) == self.opts.needs;
        if can_switch {
            if let Some((target, tx, ty)) = self.layout.switch_target(self.active, x, y, dx, dy, self.now) {
                if target == self.primary || self.connection(target).is_some() {
                    if let Some(c) = self.connection(self.active) {
                        if let Some(p) = self.peers.get_mut(&c) {
                            p.ledger.release_remote(c, out);
                        }
                        send(c, Message::Leave, out);
                    } else {
                        out.push(Action::ReleaseAllLocal);
                    }
                    self.active = target;
                    self.cursor = (tx, ty);
                    self.sequence = self.sequence.wrapping_add(1);
                    self.last_motion = (0, 0);
                    if let Some(c) = self.connection(target) {
                        send(
                            c,
                            Message::Enter {
                                x: i16c(tx),
                                y: i16c(ty),
                                sequence: self.sequence,
                                modifiers: self.local.modifiers,
                            },
                            out,
                        );
                        out.push(Action::HideLocalCursor(true));
                        self.push_slots(c, out);
                    } else {
                        out.push(Action::HideLocalCursor(false));
                        out.push(Action::WarpLocalCursor { x: tx, y: ty });
                    }
                    return;
                }
            }
        } else {
            self.layout.reset();
        }
        self.cursor = self.layout.rect(self.active).clamp(x, y);
        if let Some(c) = self.connection(self.active) {
            send(
                c,
                Message::MouseMoveAbs {
                    x: i16c(self.cursor.0),
                    y: i16c(self.cursor.1),
                },
                out,
            );
        }
    }
    fn push_slots(&mut self, conn: ConnId, out: &mut Vec<Action>) {
        let Some(p) = self.peers.get_mut(&conn) else { return };
        if p.phase != Phase::Ready
            || p.version.minor < 6
            || !p.options.clipboard
            || !self.config.clipboard.enabled
            || !self.config.clipboard.send
        {
            return;
        }
        for (i, s) in self.slots.iter_mut().enumerate() {
            if s.owner != Some(conn) {
                if s.data.is_none() {
                    if let Some(data) = &s.remote_payload {
                        match clipboard::marshal(data, self.config.clipboard.max_bytes) {
                            Ok(bytes) => s.data = Some(Arc::new(bytes)),
                            Err(_) => {
                                clipboard::blocked(data.total_bytes(), self.config.clipboard.max_bytes, &p.name, out);
                                continue;
                            }
                        }
                    }
                }
                if let Some(bytes) = &s.data {
                    let limit = p.options.limit.min(self.config.clipboard.max_bytes);
                    if bytes.len() > limit {
                        clipboard::blocked(bytes.len(), limit, &p.name, out);
                    } else {
                        send(
                            conn,
                            Message::ClipboardGrab {
                                id: ClipboardId(i as u8),
                                sequence: 0,
                            },
                            out,
                        );
                        p.transfers.enqueue(ClipboardId(i as u8), 0, bytes.clone());
                    }
                } else if s.available && !s.readback {
                    s.readback = true;
                    out.push(Action::ReadClipboard {
                        id: ClipboardId(i as u8),
                        max_bytes: self.config.clipboard.max_bytes.min(clipboard::HARD_CAP),
                    });
                }
            }
        }
    }
    fn payload(&mut self, owner: Option<ConnId>, id: ClipboardId, data: ClipboardData, out: &mut Vec<Action>) {
        if !self.config.clipboard.enabled
            || (owner.is_none() && !self.config.clipboard.send)
            || (owner.is_some() && !self.config.clipboard.receive)
        {
            return;
        }
        let Some(slot) = self.slots.get_mut(id.0 as usize) else {
            return;
        };
        let readback = owner.is_none() && slot.readback;
        let owner = if readback { slot.owner } else { owner };
        slot.readback = false;
        if slot.owner != owner {
            return;
        }
        // A readable empty clipboard is a clear. Unavailable and own-write
        // reads must arrive as ClipboardReadFailed, never an empty payload.
        match clipboard::marshal(&data, self.config.clipboard.max_bytes) {
            Ok(bytes) => {
                slot.data = Some(Arc::new(bytes));
                slot.available = true;
            }
            Err(_) => {
                clipboard::blocked(data.total_bytes(), self.config.clipboard.max_bytes, "local", out);
                return;
            }
        }
        if owner.is_some() && !readback {
            clipboard::transferred(&data, "in", out);
            let data = Arc::new(data);
            slot.remote_payload = Some(data.clone());
            out.push(Action::SetClipboardShared { id, data });
        } else {
            clipboard::transferred(&data, "out", out);
        }
        let conns = self
            .peers
            .keys()
            .copied()
            .filter(|c| Some(*c) != owner)
            .collect::<Vec<_>>();
        for c in conns {
            self.push_slots(c, out);
        }
    }
}

use crate::{clipboard, common::*, layout::Rect, notify, Action, ClientEvent, CloseReason, ConnId};
use openergy_config::Config;
use openergy_platform::{ClipboardData, InputEvent, Modifiers};
use openergy_protocol::{ClipboardId, Message};
use std::sync::Arc;

#[derive(Clone)]
pub struct Client {
    config: Arc<Config>,
    screen_name: String,
    peer: Option<(ConnId, Peer)>,
    now: u64,
    screen: Rect,
    cursor: (i32, i32),
    active: bool,
    ignore_mouse: bool,
    sequence: u32,
    synthetic_modifiers: u16,
    clip_sequences: [u32; 2],
    local_owner: [bool; 2],
    ledger: Ledger,
}
impl Client {
    pub fn new(config: Arc<Config>, screen_name: String) -> Self {
        Self {
            config,
            screen_name,
            peer: None,
            now: 0,
            screen: Rect::default(),
            cursor: (0, 0),
            active: false,
            ignore_mouse: true,
            sequence: 0,
            synthetic_modifiers: 0,
            clip_sequences: [0; 2],
            local_owner: [false; 2],
            ledger: Ledger::default(),
        }
    }
    pub fn abort_clipboard(&mut self, conn: ConnId, id: ClipboardId) {
        if let Some((c, peer)) = &mut self.peer {
            if *c == conn {
                peer.transfers.cancel(id);
            }
        }
    }
    pub fn next_deadline_ms(&self) -> u64 {
        self.peer
            .as_ref()
            .map(|(_, p)| p.next_deadline(self.now, false))
            .unwrap_or(self.now + 1000)
    }
    pub fn config(&self) -> &Config {
        &self.config
    }
    pub fn screen_name(&self) -> &str {
        &self.screen_name
    }
    pub fn remote_active(&self) -> bool {
        self.active
    }
    pub fn is_connected(&self) -> bool {
        self.peer.as_ref().is_some_and(|(_, p)| p.phase == Phase::Ready)
    }
    pub fn snapshot(&self) -> SessionSnapshot {
        SessionSnapshot {
            active_screen: self.active.then(|| self.screen_name.clone()),
            cursor: Some(self.cursor),
            peers: self.peer.iter().map(|(c, p)| p.snapshot(*c)).collect(),
            connected: self.peer.as_ref().is_some_and(|(_, p)| p.phase == Phase::Ready),
            remote_active: self.active,
        }
    }
    fn leave(&mut self, out: &mut Vec<Action>) {
        self.active = false;
        self.ledger.clear();
        self.synthetic_modifiers = 0;
        out.push(Action::ReleaseAllLocal);
        out.push(Action::HideLocalCursor(false));
        if let Some((_, p)) = &mut self.peer {
            p.secure_input = None;
        }
    }
    fn disconnect(&mut self, out: &mut Vec<Action>) {
        self.leave(out);
        if let Some((c, _)) = self.peer.take() {
            close(c, CloseReason::Normal, out);
            notify("peer.disconnected", serde_json::json!({}), out);
        }
    }
    pub fn handle(&mut self, ev: ClientEvent, out: &mut Vec<Action>) {
        match ev {
            ClientEvent::ServerConnected { conn } => {
                self.leave(out);
                // CINN serials and clipboard ownership belong to this
                // connection, including when the server restarted at zero.
                self.sequence = 0;
                self.clip_sequences = [0; 2];
                self.local_owner = [false; 2];
                let mut p = Peer::new(self.now);
                p.name = "server".into();
                p.options.heartbeat = self.config.client.heartbeat_ms;
                self.peer = Some((conn, p));
                self.ignore_mouse = true;
            }
            ClientEvent::ServerMessage { conn, msg } => {
                if self.peer.as_ref().is_some_and(|(c, _)| *c == conn) {
                    self.message(msg, out);
                }
            }
            ClientEvent::ServerDisconnected { conn, .. } => {
                if self.peer.as_ref().is_some_and(|(c, _)| *c == conn) {
                    self.leave(out);
                    self.peer = None;
                    notify("peer.disconnected", serde_json::json!({}), out);
                }
            }
            ClientEvent::LocalScreen { rect, cursor } => {
                self.screen = rect;
                self.cursor = rect.clamp(cursor.0, cursor.1);
            }
            ClientEvent::DisplayChanged => {
                if let Some((c, p)) = &self.peer {
                    if p.phase != Phase::Hello {
                        send(*c, screen_info(self.screen, self.cursor), out);
                        self.ignore_mouse = true;
                    }
                }
            }
            ClientEvent::PermissionLost => {
                notice("permission_denied", "Input permission lost", out);
                self.disconnect(out);
            }
            ClientEvent::TimerTick { now_ms } => {
                self.now = now_ms;
                if let Some((c, p)) = &mut self.peer {
                    if p.tick(*c, now_ms, false, out) {
                        log::warn!("server heartbeat/setup timeout");
                        self.disconnect(out);
                    }
                }
            }
            ClientEvent::ConfigChanged(cfg) => {
                let clipboard_changed = self.config.clipboard != cfg.clipboard;
                let was_active = self.active;
                self.leave(out);
                self.active = was_active;
                self.config = cfg;
                self.screen_name = self.config.name.clone();
                if clipboard_changed {
                    if let Some((_, p)) = &mut self.peer {
                        p.transfers = Default::default();
                    }
                }
            }
            ClientEvent::LocalClipboardChanged { id } => {
                if id.0 < 2 && self.config.clipboard.enabled && self.config.clipboard.send {
                    if let Some((_, p)) = &mut self.peer {
                        if p.phase == Phase::Ready && p.version.minor >= 6 {
                            if let Some(v) = self.local_owner.get_mut(id.0 as usize) {
                                *v = true;
                            }
                            if let Some(v) = self.clip_sequences.get_mut(id.0 as usize) {
                                *v = self.sequence;
                            }
                            p.transfers.cancel(id);
                            out.push(Action::ReadClipboard {
                                id,
                                max_bytes: self.config.clipboard.max_bytes.min(clipboard::HARD_CAP),
                            });
                        }
                    }
                }
            }
            ClientEvent::ClipboardPayload { id, data } => self.payload(id, data, out),
            ClientEvent::ClipboardReadFailed { id } => {
                if let Some(owner) = self.local_owner.get_mut(id.0 as usize) {
                    *owner = false;
                }
            }
            ClientEvent::Shutdown => {
                self.leave(out);
                if let Some((c, _)) = &self.peer {
                    send(*c, Message::Bye, out);
                }
                self.peer = None;
            }
            ClientEvent::ReconnectTimer => {}
        }
    }
    fn message(&mut self, msg: Message, out: &mut Vec<Action>) {
        let Some((conn, p)) = &mut self.peer else { return };
        let c = *conn;
        p.last_rx = self.now;
        p.observe_language(&msg);
        if let Message::Unknown { code, .. } = msg {
            p.unknown(code);
            return;
        }
        if matches!(
            msg,
            Message::Bye
                | Message::ErrorBusy
                | Message::ErrorBad
                | Message::ErrorUnknown
                | Message::ErrorIncompatible { .. }
        ) {
            if matches!(msg, Message::ErrorBusy) {
                log::warn!("server rejected duplicate name (EBSY); retry with backoff");
                notice("busy", "Server name is busy; reconnect will back off", out);
            } else if matches!(msg, Message::ErrorUnknown) {
                notice("unknown_screen", "The server has no screen with this name.", out);
            } else if !matches!(msg, Message::Bye) {
                notice("protocol_error", "The server rejected the connection protocol.", out);
            }
            self.disconnect(out);
            return;
        }
        if p.phase == Phase::Hello {
            if let Message::Hello { product, version } = msg {
                if version.major != 1
                    || !(product.eq_ignore_ascii_case("Synergy") || product.eq_ignore_ascii_case("Barrier"))
                {
                    notice(
                        "protocol_error",
                        "The server uses an unsupported protocol version.",
                        out,
                    );
                    self.disconnect(out);
                    return;
                }
                if version.minor > 8 {
                    log::info!("server protocol minor {} accepted as 1.8", version.minor);
                }
                p.product = product.clone();
                let version = openergy_protocol::ProtocolVersion {
                    major: 1,
                    minor: version.minor.min(8),
                };
                p.version = version;
                p.phase = Phase::Info;
                send(
                    c,
                    Message::HelloBack {
                        product,
                        version,
                        name: self.screen_name.clone(),
                    },
                    out,
                );
            } else {
                self.disconnect(out);
            }
            return;
        }
        match msg {
            Message::QueryInfo => {
                send(c, screen_info(self.screen, self.cursor), out);
                self.ignore_mouse = true;
            }
            Message::InfoAck => self.ignore_mouse = false,
            Message::LanguageSync { languages } if p.phase == Phase::Info => {
                if languages.len() % 2 != 0 {
                    if !p.language_warned {
                        p.language_warned = true;
                        log::warn!("odd language list ignored");
                    }
                } else {
                    p.languages = languages.as_bytes().as_chunks::<2>().0.to_vec();
                }
            }
            Message::KeepAlive => {
                p.alive(self.now);
                send(c, Message::KeepAlive, out);
                p.last_sent = self.now;
            }
            Message::ResetOptions => {
                p.options = Options::default();
                p.last_alive = self.now;
            }
            Message::SetOptions { options } => {
                p.options.apply(&options);
                p.last_alive = self.now;
                if p.phase != Phase::Ready {
                    p.phase = Phase::Ready;
                    notify("peer.connected", serde_json::json!({"name":"server"}), out);
                }
            }
            Message::Enter {
                x,
                y,
                sequence,
                modifiers,
            } if p.phase == Phase::Ready => {
                self.ledger.clear();
                out.push(Action::ReleaseAllLocal);
                self.active = true;
                self.sequence = sequence;
                self.cursor = self.screen.clamp(i32::from(x), i32::from(y));
                let modifiers = p.options.mapped_mask(modifiers);
                self.ledger.modifiers = modifiers;
                self.synthetic_modifiers = modifiers & 0x3f;
                out.push(Action::HideLocalCursor(false));
                out.push(Action::Inject(InputEvent::MouseMoveAbs {
                    x: self.cursor.0,
                    y: self.cursor.1,
                }));
                for (mask, key) in [
                    (Modifiers::SHIFT, 0xefe1),
                    (Modifiers::CONTROL, 0xefe3),
                    (Modifiers::ALT, 0xefe9),
                    (Modifiers::META, 0xefe7),
                    (Modifiers::SUPER, 0xefeb),
                    (Modifiers::ALTGR, 0xef7e),
                ] {
                    let button = key;
                    if modifiers & mask != 0 {
                        let ev = InputEvent::KeyDown {
                            key,
                            modifiers: Modifiers(modifiers),
                            button,
                        };

                        self.ledger.observe(&ev);
                        out.push(Action::Inject(ev));
                    }
                }
            }
            Message::Leave => self.leave(out),
            Message::ClipboardGrab { id, sequence: _ } if id.0 == 0 && p.phase == Phase::Ready => {
                if let Some(v) = self.local_owner.get_mut(id.0 as usize) {
                    *v = false;
                }
                if let Some(v) = self.clip_sequences.get_mut(id.0 as usize) {
                    *v = 0;
                }
                p.transfers.cancel(id);
            }
            Message::ClipboardData { id, sequence, chunk }
                if id.0 == 0
                    && p.phase == Phase::Ready
                    && self.config.clipboard.enabled
                    && self.config.clipboard.receive =>
            {
                let declared = if let openergy_protocol::Chunk::Start { total_len } = &chunk {
                    Some(*total_len as usize)
                } else {
                    None
                };
                match p
                    .transfers
                    .receive(id, sequence, chunk, self.config.clipboard.max_bytes, self.now)
                {
                    Ok(Some(data)) => {
                        if let Some(v) = self.local_owner.get_mut(id.0 as usize) {
                            *v = false;
                        }
                        // The platform clipboard is shared on macOS. An empty
                        // X11 selection must not erase a populated normal clip.
                        if id.0 == 0 || !data.formats.is_empty() {
                            clipboard::transferred(&data, "in", out);
                            out.push(Action::SetClipboard { id, data });
                        }
                    }
                    Ok(None) => {}
                    Err(clipboard::ClipboardError::TooLarge) => clipboard::blocked(
                        declared.unwrap_or(0),
                        self.config.clipboard.max_bytes.min(clipboard::HARD_CAP),
                        &p.name,
                        out,
                    ),
                    Err(e) => log::warn!("discarded clipboard: {e:?}"),
                }
            }
            Message::SecureInputNotification { name } => {
                p.secure_input = (!name.is_empty()).then_some(name);
                log::info!("peer secure-input status changed");
            }
            Message::ScreenSaver { on } => notify("peer.screensaver", serde_json::json!({"on":on}), out),
            Message::FileTransfer { payload, .. } => p.decline(payload.len(), out),
            Message::DragInfo { payload, .. } => p.decline(payload.len(), out),
            other => {
                if self.active && p.phase == Phase::Ready {
                    if let Some(mut ev) = input_message(other, &p.options) {
                        match ev {
                            InputEvent::MouseMoveAbs { x, y } => {
                                if self.ignore_mouse {
                                    return;
                                }
                                self.cursor = self.screen.clamp(x, y);
                                ev = InputEvent::MouseMoveAbs {
                                    x: self.cursor.0,
                                    y: self.cursor.1,
                                };
                            }
                            InputEvent::MouseMoveRel { dx, dy } => {
                                if self.ignore_mouse {
                                    return;
                                }
                                self.cursor = self
                                    .screen
                                    .clamp(self.cursor.0.saturating_add(dx), self.cursor.1.saturating_add(dy));
                            }
                            InputEvent::MouseWheel { dx, dy } => {
                                ev = InputEvent::MouseWheel {
                                    dx: (dx as f64 * self.config.input.scroll_sensitivity) as i32,
                                    dy: (dy as f64
                                        * self.config.input.scroll_sensitivity
                                        * if self.config.input.invert_scroll_y { -1.0 } else { 1.0 })
                                        as i32,
                                };
                            }
                            _ => {}
                        }
                        if let InputEvent::KeyUp { key, modifiers, button } = &ev {
                            let mask = match *key {
                                0xefe1 | 0xefe2 => 1,
                                0xefe3 | 0xefe4 => 2,
                                0xefe9 | 0xefea => 4,
                                0xefe7 | 0xefe8 => 8,
                                0xefeb | 0xefec => 16,
                                0xef7e => 32,
                                _ => 0,
                            };
                            let synthetic_key = match mask {
                                1 => 0xefe1,
                                2 => 0xefe3,
                                4 => 0xefe9,
                                8 => 0xefe7,
                                16 => 0xefeb,
                                _ => 0xef7e,
                            };
                            // A second physical modifier may have been pressed
                            // after entry. Its up must release that physical key,
                            // not consume the modifier synthesized by CINN.
                            if self.synthetic_modifiers & mask != 0 {
                                let physical = *button != synthetic_key && self.ledger.has_key(*key, *button);
                                // CINN has a modifier mask, not the identities
                                // of keys held before entry. Either side may
                                // release first; keep the synthetic key until
                                // the aggregate modifier bit clears.
                                if modifiers.0 & mask == 0 {
                                    self.synthetic_modifiers &= !mask;
                                    let release = InputEvent::KeyUp {
                                        key: synthetic_key,
                                        modifiers: *modifiers,
                                        button: synthetic_key,
                                    };
                                    self.ledger.observe(&release);
                                    out.push(Action::Inject(release));
                                }
                                if !physical {
                                    return;
                                }
                            }
                        }
                        self.ledger.observe(&ev);
                        out.push(Action::Inject(ev));
                    }
                }
            }
        }
    }
    fn payload(&mut self, id: ClipboardId, data: ClipboardData, out: &mut Vec<Action>) {
        if id.0 > 1
            || !self.config.clipboard.enabled
            || !self.config.clipboard.send
            || !self.local_owner.get(id.0 as usize).copied().unwrap_or(false)
        {
            return;
        }
        let Some((conn, p)) = &mut self.peer else { return };
        if p.phase != Phase::Ready || !p.options.clipboard {
            return;
        }
        let limit = p.options.limit.min(self.config.clipboard.max_bytes);
        match clipboard::marshal(&data, self.config.clipboard.max_bytes) {
            Ok(bytes) if bytes.len() < limit => {
                // A blocked payload must not take ownership from a peer that
                // still has a useful clipboard.
                send(
                    *conn,
                    Message::ClipboardGrab {
                        id,
                        sequence: self.sequence,
                    },
                    out,
                );
                p.transfers.enqueue(id, self.sequence, Arc::new(bytes));
                clipboard::transferred(&data, "out", out);
            }
            Ok(bytes) => clipboard::blocked(bytes.len(), limit, &p.name, out),
            Err(_) => clipboard::blocked(data.total_bytes(), limit, &p.name, out),
        }
    }
}
